<?php $pageTitle='Delivery'; require __DIR__.'/_header.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$id=(int)$_POST['id'];$q=db()->prepare('UPDATE delivery_zones SET name=?,price=?,requires_quote=?,max_distance_km=?,active=? WHERE id=?');$q->execute([trim($_POST['name']), (float)$_POST['price'], isset($_POST['requires_quote'])?1:0, $_POST['max_distance_km']===''?null:(float)$_POST['max_distance_km'], isset($_POST['active'])?1:0,$id]);}$rows=db()->query('SELECT * FROM delivery_zones ORDER BY sort_order,id')->fetchAll();?><section class="admin-card"><p>Puedes cambiar nombres y precios sin editar código. Si configuras distancias máximas y la ubicación del negocio, el frontend queda preparado para automatización futura.</p><div class="table-wrap"><table><thead><tr><th>Zona</th><th>Precio</th><th>Km máx.</th><th>Por confirmar</th><th>Activo</th><th></th></tr></thead><tbody><?php foreach($rows as $z):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$z['id']?>"><td><input name="name" value="<?=h($z['name'])?>"></td><td><input type="number" step="0.01" name="price" value="<?=h((string)$z['price'])?>"></td><td><input type="number" step="0.1" name="max_distance_km" value="<?=h((string)$z['max_distance_km'])?>"></td><td><input type="checkbox" name="requires_quote" <?=$z['requires_quote']?'checked':''?>></td><td><input type="checkbox" name="active" <?=$z['active']?'checked':''?>></td><td><button class="btn small primary">Guardar</button></td></form></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>